// Generated by build.mjs. Cache name changes whenever any site file changes.
const VERSION='26573139ea3245ec';
const PREFIX='fin-calc:'+self.registration.scope+':';
const CACHE=PREFIX+VERSION;
const PRECACHE=["./","./index.html","./manifest.webmanifest","./apple-touch-icon.png","./icon-192.png","./icon-512.png","./icon-maskable-512.png","./favicon.ico"];
const INDEX=new URL('./index.html',self.registration.scope).href;
// Safari refuses redirected responses for navigations; store a clean copy instead.
const clean=async r=>r.redirected?new Response(await r.blob(),{status:r.status,statusText:r.statusText,headers:r.headers}):r;
self.addEventListener('install',e=>{e.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 await Promise.all(PRECACHE.map(async url=>{const r=await fetch(new Request(url,{cache:'reload'}));if(!r.ok)throw new Error('Precache failed: '+url);await cache.put(url,await clean(r));}));
 await self.skipWaiting();
})());});
self.addEventListener('activate',e=>{e.waitUntil((async()=>{
 // Only this app's old caches (other apps on the same origin keep theirs).
 for(const k of await caches.keys())if(k.startsWith(PREFIX)&&k!==CACHE)await caches.delete(k);
 await self.clients.claim();
})());});
self.addEventListener('fetch',e=>{
 const req=e.request;
 if(req.method!=='GET'||new URL(req.url).origin!==self.location.origin)return;
 e.respondWith((async()=>{
  const cache=await caches.open(CACHE);
  if(req.mode==='navigate'){
   const hit=await cache.match(req,{ignoreSearch:true});
   if(hit)return hit;
   try{return await fetch(req);}catch(err){const index=await cache.match(INDEX);if(index)return index;throw err;}
  }
  return (await cache.match(req))||fetch(req);
 })());
});
